//! Id and timestamp generation at the storage boundary. See
//! AGENT-BRIEF.md "Style": ids are ULIDs as 26-char strings, generated by
//! the caller; timestamps are ISO-8601 UTC strings at the storage boundary.

use chrono::SecondsFormat;
use std::sync::{Mutex, OnceLock};
use ulid::{Generator, Ulid};

/// A new 26-char Crockford-base32 ULID, as a string.
///
/// # Why this is monotonic, and why that matters
///
/// ULIDs were chosen over random UUIDs because they sort by creation time
/// (03-architecture.md / 04-data-model.md), and the whole design leans on
/// that: every list orders by `created_at DESC, id DESC`, and `id` is what
/// breaks the tie when two rows share a timestamp.
///
/// A plain `Ulid::new()` does NOT give that. Its 48-bit timestamp has
/// millisecond resolution and its low 80 bits are random, so two ids minted
/// in the same millisecond sort in an arbitrary order. Sorting is only
/// stable *across* milliseconds — which is invisible in casual use and then
/// wrong under exactly the conditions that matter: an agent writing a batch,
/// or an import creating rows as fast as the machine allows. The visible
/// damage is not a cosmetic mis-ordering but broken pagination — with an
/// unstable sort, a row can appear on two consecutive pages, or on neither.
///
/// `ulid::Generator` fixes this properly: within the same millisecond it
/// increments the previous random component instead of drawing a fresh one,
/// so ids are strictly increasing. That restores the property the rest of
/// the codebase assumes.
///
/// This applies to ids the server mints. A caller may supply its own id
/// (see `is_valid_id`), and nothing can make someone else's ULID monotonic
/// with respect to ours — so `created_at DESC, id DESC` remains the ordering
/// contract, with this function guaranteeing the tiebreaker is meaningful
/// for everything we generate ourselves.
pub fn new_id() -> String {
    static GEN: OnceLock<Mutex<Generator>> = OnceLock::new();
    let mut generator = GEN
        .get_or_init(|| Mutex::new(Generator::new()))
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner());
    // `generate` only fails if the random component overflows within one
    // millisecond (2^80 ids), which cannot happen in practice; falling back
    // to a random ULID keeps the process alive rather than panicking, at the
    // cost of one possibly-unordered id.
    generator
        .generate()
        .unwrap_or_else(|_| Ulid::new())
        .to_string()
}

/// The current instant as an ISO-8601 UTC string with millisecond precision
/// and a `Z` suffix (e.g. `2026-09-09T12:00:00.000Z`).
pub fn now() -> String {
    chrono::Utc::now().to_rfc3339_opts(SecondsFormat::Millis, true)
}

/// Whether `s` is a well-formed ULID — 26 Crockford-base32 characters that
/// also fit the 48-bit timestamp and 80-bit randomness a ULID is made of.
///
/// The service layer needs this because the HTTP and MCP surfaces let a
/// caller supply the id of the thing it is creating (AGENT-BRIEF.md
/// "Style": "Ids are ULIDs as 26-char strings, generated by the caller
/// where the API allows"), and an id that is not a ULID has to be refused
/// with a usable message rather than stored.
pub fn is_valid_id(s: &str) -> bool {
    Ulid::from_string(s).is_ok()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn generated_ids_are_valid_and_generated_timestamps_are_iso8601_utc() {
        let id = new_id();
        assert_eq!(id.len(), 26);
        assert!(is_valid_id(&id));

        let now = now();
        assert!(now.ends_with('Z'), "{now} should be UTC with a Z suffix");
        assert!(chrono::DateTime::parse_from_rfc3339(&now).is_ok());
    }

    #[test]
    fn ids_minted_in_the_same_millisecond_still_sort_in_creation_order() {
        // The regression this pins: `Ulid::new()` randomises the low 80 bits,
        // so a burst of ids inside one millisecond sorted arbitrarily. Every
        // list in the product orders by `created_at DESC, id DESC` and relies
        // on `id` to break the tie, so an unstable sort here shows up as a row
        // appearing on two pages or on none. 500 ids in a tight loop are
        // comfortably inside one millisecond on any machine that matters.
        let ids: Vec<String> = (0..500).map(|_| new_id()).collect();

        let mut sorted = ids.clone();
        sorted.sort();
        assert_eq!(
            ids, sorted,
            "ids must be strictly increasing in creation order, even within a millisecond"
        );

        let unique: std::collections::HashSet<&String> = ids.iter().collect();
        assert_eq!(unique.len(), ids.len(), "ids must be unique");
    }

    #[test]
    fn ids_that_are_not_ulids_are_rejected() {
        for bad in [
            "",
            "nope",
            "01ARZ3NDEKTSV4RRFFQ69G5FA",
            "not-a-ulid-but-26-chars-x",
        ] {
            assert!(!is_valid_id(bad), "{bad} is not a ULID");
        }
    }
}
